mapper.select:
SELECT COALESCE (sit.taskNum,0) as taskNum, mc.market_tenant, mc.market_name FROM market_config mc LEFT JOIN ( select sit2.market_tenant,sit2.market_name,count(sit2.id) as taskNum from safety_inspect_task sit2
left join safety_inspect_record sir on sir.task_id = sit2.id
and sit2.create_time >= #{query.period.begin} and sit2.create_time < #{query.period.end}
and sir.result = 'ABNORMAL'
and sir.result = 'NORMAL'
and sit2.market_tenant = #{query.marketTenant}
and sit2.status_code = #{query.taskStatus}
group by sit2.market_tenant order by taskNum desc ) sit ON mc.market_tenant = sit.market_tenant
mc.status = true

SELECT COALESCE (sit.num,0) as taskNum, mc.market_tenant, mc.market_name FROM market_config mc LEFT JOIN ( select t1.market_tenant, t1.market_name, count(t1.market_name) as num from (select siri.market_tenant,siri.market_name from safety_inspect_record_item siri inner join safety_inspect_record sir on(sir.id=siri.record_id)
siri.error_value_flag = 1
and sir.`time` >= #{query.period.begin} and sir.`time` < #{query.period.end}
and siri.item_tag is not null
and siri.item_tag in
#{tag}
group by siri.market_tenant, siri.record_id ) t1 group by t1.market_tenant ORDER BY num ) sit ON mc.market_tenant = sit.market_tenant
mc.status = true
and mc.market_tenant = #{query.marketTenant}
order by taskNum desc

select sit.* from safety_inspect_task sit left join market_config mc on mc.market_tenant = sit.market_tenant
mc.status = true
and sit.task_create_time >= #{query.period.begin} and sit.task_create_time < #{query.period.end}
and sit.market_tenant = #{query.marketTenant}

select distinct
sit.*
from
safety_inspect_task sit
left join market_config mc on mc.market_tenant = sit.market_tenant

    left join safety_inspect_record sir on sir.task_id = sit.id


    mc.status = true

        and sir.result = 'ABNORMAL'


        and sir.result = 'NORMAL'


        and sir.time >= #{query.execPeriod.begin} and sir.time < #{query.execPeriod.end}


        and sit.task_create_time >= #{query.period.begin} and sit.task_create_time < #{query.period.end}


        and sit.market_tenant = #{query.marketTenant}


        and sit.status_code = #{query.state}


        and sit.type_name = #{query.typeName}


order by sit.task_create_time desc

select count(sit.id) as total_num from safety_inspect_task sit left join market_config mc on mc.market_tenant = sit.market_tenant
mc.status = true
and sit.status_code in
#{state}
and sit.market_tenant = #{query.marketTenant}

SELECT t.status_code AS groupKey, COUNT( 1 ) AS count FROM safety_inspect_task t LEFT JOIN market_config mc ON mc.market_tenant = t.market_tenant
mc.status = true
AND t.market_tenant IN
#{id}
AND t.task_create_time BETWEEN #{query.createdPeriod.begin} AND #{query.createdPeriod.end}
GROUP BY t.status_code
